import AppKit
import Carbon
import CoreGraphics
import TranscribeKit

/// Puts a dictation's text where the user is typing (the only file that posts events, snapshots and restores the
/// general pasteboard, reads Secure Event Input and the frontmost app).
///
/// A paste: write the text to the clipboard (this Mac only, marked transient and auto-generated so clipboard managers
/// skip it; never "concealed", which means a password), press ⌘V for the user, then put their clipboard back. No
/// AppleScript, System Events or Accessibility text insertion: those need entitlements the release forbids.
///
/// The text is only copied ("Copied — press ⌘V") when Accessibility is not allowed, a password field has Secure Event
/// Input on, or the app in front is no longer the one the dictation ended in (`PasteDecision`).
///
/// The clipboard comes back only when macOS lets Transcribe read it without asking (`accessBehavior == .alwaysAllow`),
/// and only if nothing else wrote it in the meantime. A paste while the previous paste's restore is still waiting, and
/// the clipboard still holds that paste's dictation, carries the restore's snapshot forward (`RestorePlan`); if the user
/// copied something in between, that copy is snapshotted instead.
@MainActor final class PasteService: DictationOutput {
    private let permissions: ShortcutPermissions

    /// The user's clipboard as it was before a paste, waiting to be put back.
    private struct PendingRestore {
        let id: UUID
        let snapshot: ClipboardSnapshot?
        /// The clipboard's change count right after the paste wrote it: while it still matches, the clipboard holds
        /// that paste's dictation, not anything of the user's.
        let changeCountAfterWrite: Int
        let task: Task<Void, Never>
    }
    private var pending: PendingRestore?

    static let transientType = NSPasteboard.PasteboardType("org.nspasteboard.TransientType")
    static let autoGeneratedType = NSPasteboard.PasteboardType("org.nspasteboard.AutoGeneratedType")

    init(permissions: ShortcutPermissions) {
        self.permissions = permissions
    }

    func noteTarget() -> Int32? {
        NSWorkspace.shared.frontmostApplication?.processIdentifier
    }

    func deliver(_ text: String, target: Int32?) async -> DeliveryOutcome {
        permissions.refresh()
        let board = NSPasteboard.general
        let plan = PasteDecision.plan(postEventAllowed: ShortcutPermissions.postEventGranted(),
                                      secureInput: IsSecureEventInputEnabled(),
                                      targetUnchanged: target == nil || target == noteTarget(),
                                      clipboardReadable: board.accessBehavior == .alwaysAllow)
        let restoreClipboard: Bool
        switch plan {
        case .copyOnly(let reason): return copy(text, reason: reason)
        case .paste(let restore): restoreClipboard = restore
        }

        // ⌘V with the shortcut's fn, ⌥ or ⇧ still held would be another key: wait for the user to let go.
        await waitForModifiersUp()
        if let target, target != noteTarget() { return copy(text, reason: .appChanged) }

        let source = RestorePlan.snapshotSource(pendingChangeCount: pending?.changeCountAfterWrite,
                                                changeCountNow: board.changeCount, clipboardReadable: restoreClipboard)
        let carried = pending?.snapshot
        pending?.task.cancel()
        pending = nil
        let snapshot: ClipboardSnapshot?
        switch source {
        case .carryPending: snapshot = carried
        case .takeNew: snapshot = ClipboardSnapshot(board)
        case .none: snapshot = nil
        }

        let written = write(text)
        try? await Task.sleep(for: PasteDecision.prePasteDelay)
        postCommandV()
        scheduleRestore(snapshot, changeCountAfterWrite: written)
        return .pasted
    }

    func copy(_ text: String, reason: CopyReason) -> DeliveryOutcome {
        // The text must stay: a restore still waiting from an earlier paste would replace it.
        pending?.task.cancel()
        pending = nil
        write(text)
        return .copied(reason)
    }

    // MARK: - Steps

    /// Writes the text as the only item; returns the change count after the write.
    @discardableResult
    private func write(_ text: String) -> Int {
        let board = NSPasteboard.general
        board.prepareForNewContents(with: .currentHostOnly)
        let item = NSPasteboardItem()
        item.setString(text, forType: .string)
        item.setString("", forType: Self.transientType)
        item.setString("", forType: Self.autoGeneratedType)
        board.writeObjects([item])
        return board.changeCount
    }

    /// Polls the physical modifier state until no ⌃ ⌥ ⇧ ⌘ or fn is held, for at most `PasteDecision.modifierWait`.
    private func waitForModifiersUp() async {
        let held: CGEventFlags = [.maskControl, .maskAlternate, .maskShift, .maskCommand, .maskSecondaryFn]
        let deadline = ContinuousClock.now + PasteDecision.modifierWait
        while !CGEventSource.flagsState(.combinedSessionState).intersection(held).isEmpty, ContinuousClock.now < deadline {
            try? await Task.sleep(for: PasteDecision.modifierPoll)
        }
    }

    /// ⌘ and the key that types "v" in the current layout, posted to the session as the user's own key press would be.
    /// Local keyboard events are suppressed briefly, so a key the user presses at that instant cannot merge into it.
    private func postCommandV() {
        let source = CGEventSource(stateID: .combinedSessionState)
        source?.setLocalEventsFilterDuringSuppressionState([.permitLocalMouseEvents, .permitSystemDefinedEvents],
                                                           state: .eventSuppressionStateSuppressionInterval)
        let key = CGKeyCode(KeyboardLayout.keyCodeTypingV() ?? KeyCodes.v)
        let down = CGEvent(keyboardEventSource: source, virtualKey: key, keyDown: true)
        let up = CGEvent(keyboardEventSource: source, virtualKey: key, keyDown: false)
        down?.flags = .maskCommand
        up?.flags = .maskCommand
        down?.post(tap: .cgSessionEventTap)
        up?.post(tap: .cgSessionEventTap)
    }

    /// After `PasteDecision.restoreDelay` (the target app reads the clipboard in that time), puts the snapshot back if
    /// nothing has written the clipboard since. Even without a snapshot a restore is "pending" for that time, so a
    /// paste right after this one does not snapshot this dictation's text as if it were the user's.
    private func scheduleRestore(_ snapshot: ClipboardSnapshot?, changeCountAfterWrite: Int) {
        let id = UUID()
        let task = Task { [weak self] in
            try? await Task.sleep(for: PasteDecision.restoreDelay)
            guard !Task.isCancelled, let self else { return }
            let board = NSPasteboard.general
            if let snapshot, RestorePlan.shouldRestore(changeCountNow: board.changeCount,
                                                       changeCountAfterWrite: changeCountAfterWrite, hasSnapshot: true) {
                snapshot.restore(to: board)
            }
            if self.pending?.id == id { self.pending = nil }
        }
        pending = PendingRestore(id: id, snapshot: snapshot, changeCountAfterWrite: changeCountAfterWrite, task: task)
    }
}

/// A copy of every item on the clipboard, type by type. Promised data (file promises, which would make the source app
/// produce the file now) is left out, and so is a clipboard larger than `PasteDecision.snapshotLimitBytes` in total:
/// then there is nothing to put back.
struct ClipboardSnapshot {
    private let items: [[(NSPasteboard.PasteboardType, Data)]]

    init?(_ board: NSPasteboard) {
        var total = 0
        var items: [[(NSPasteboard.PasteboardType, Data)]] = []
        for item in board.pasteboardItems ?? [] {
            var entries: [(NSPasteboard.PasteboardType, Data)] = []
            for type in item.types where !type.rawValue.localizedCaseInsensitiveContains("promise") {
                guard let data = item.data(forType: type) else { continue }
                total += data.count
                if total > PasteDecision.snapshotLimitBytes { return nil }
                entries.append((type, data))
            }
            if !entries.isEmpty { items.append(entries) }
        }
        self.items = items
    }

    func restore(to board: NSPasteboard) {
        board.clearContents()
        guard !items.isEmpty else { return }
        let rebuilt = items.map { entries -> NSPasteboardItem in
            let item = NSPasteboardItem()
            for (type, data) in entries { item.setData(data, forType: type) }
            return item
        }
        board.writeObjects(rebuilt)
    }
}
